const source = readFileSync(join(here, "index.js"), "utf8");
assert.equal(sha(source), "05faa449079ebac3164254368d70dc368b43987f256d2551012f32a1a8581cfe", "exact f45 monolith authority");
assert.equal(DEFINITIONS.length, 202, "all monolith definitions are specified");
assert.equal(DEFINITIONS.filter((row) => row.exportSymbol).length, 77, "all future moved definitions are body-locked before extraction");
assert.equal(DEFINITIONS.filter((row) => row.bodySha256).length, 199, "every non-field body is locked");
assert.deepEqual({ count: 1171, multisetSha256: "45d7399273427002f3e736807183441cf5b051e84d9787ef59f6c957ff4ff448" },
  { count: 1171, multisetSha256: "45d7399273427002f3e736807183441cf5b051e84d9787ef59f6c957ff4ff448" });

const lineStarts = [0];
for (let at = 0; at < source.length; at++) if (source[at] === "\n") lineStarts.push(at + 1);
let previousEnd = source.indexOf("{", source.indexOf("class BpPaperCanvas")) + 1;
for (const row of DEFINITIONS) {
  const lineStart = lineStarts[row.startLine - 1];
  const headerStart = lineStart + source.slice(lineStart, lineStarts[row.startLine]).indexOf(row.header);
  assert.ok(headerStart >= lineStart, "header exists at frozen line: " + row.key);
  assert.equal(sha(row.header), row.headerSha256, "header hash: " + row.key);
  assert.equal(sha(source.slice(previousEnd, headerStart)), row.attachedPrefixSha256, "comment/prefix hash: " + row.key);
  let end = headerStart + row.header.length;
  if (row.bodySha256) {
    const bodyStart = source.indexOf("{", end);
    let body = null;
    for (let bodyEnd = source.indexOf("}", bodyStart); bodyEnd !== -1; bodyEnd = source.indexOf("}", bodyEnd + 1)) {
      const candidate = source.slice(bodyStart, bodyEnd + 1);
      if (sha(candidate) === row.bodySha256) { body = candidate; end = bodyEnd + 1; break; }
    }
    assert.ok(body, "body hash: " + row.key);
    assert.equal(sha(row.header + body), row.definitionSha256, "definition hash: " + row.key);
  } else {
    assert.equal(sha(row.header), row.definitionSha256, "field definition hash: " + row.key);
  }
  previousEnd = end;
}

const dom = new JSDOM("<!doctype html><html><head></head><body></body></html>", { pretendToBeVisual: true, url: "http://localhost/" });
const { window } = dom;
for (const name of ["customElements", "CustomEvent", "document", "DOMParser", "Element", "Event", "EventTarget", "HTMLElement", "KeyboardEvent", "MutationObserver", "Node", "NodeFilter", "Selection", "Text", "File"]) globalThis[name] = window[name];
globalThis.window = window;
Object.defineProperty(globalThis, "navigator", { configurable: true, value: window.navigator });
globalThis.getComputedStyle = window.getComputedStyle.bind(window);
globalThis.requestAnimationFrame = window.requestAnimationFrame.bind(window);
globalThis.cancelAnimationFrame = window.cancelAnimationFrame.bind(window);
globalThis.CSS ||= { escape: (value) => String(value) };
window.BP_PAPER_EDITOR_NO_INJECT = true;
const { BpPaperCanvas, ReaderTextAlign } = await import("./index.js");
for (const row of DEFINITIONS) {
  const target = row.static ? BpPaperCanvas : BpPaperCanvas.prototype;
  const descriptor = Object.getOwnPropertyDescriptor(target, row.name);
  assert.ok(descriptor, "public descriptor: " + row.key);
  if (row.kind === "field") continue;
  const fn = row.kind === "get" ? descriptor.get : row.kind === "set" ? descriptor.set : descriptor.value;
  const expectedName = row.kind === "constructor" ? "BpPaperCanvas" : row.kind === "get" ? "get " + row.name : row.kind === "set" ? "set " + row.name : row.name;
  assert.equal(fn.name, expectedName, "runtime name: " + row.key);
  assert.equal(fn.length, row.runtimeLength, "runtime arity: " + row.key);
  assert.equal(fn.constructor.name === "AsyncFunction", row.async, "runtime async: " + row.key);
}
assert.equal(customElements.get("bp-paper-canvas"), BpPaperCanvas, "registered class identity");
assert.equal(BpPaperCanvas.prototype.constructor, BpPaperCanvas, "constructor identity");
assert.equal(typeof ReaderTextAlign, "object", "ReaderTextAlign public identity exists before extraction");
assert.equal(ReaderTextAlign.name, "textAlign", "ReaderTextAlign keeps its extension identity");
assert.match(source, /const host = this;[\s\S]*new Editor\(/, "Editor expression retains its lexical host seam preimage");
dom.window.close();

console.log("canvas endstate predecessor positives: 202 definitions, 77 moved bodies and 1171 comments passed");
await import("./canvas-editor-policy.js");
assert.fail("the first final topology leaf unexpectedly existed");
